const queryClient = new QueryClient();
type IconProps = { size?: number; className?: string; strokeWidth?: number };
const iconMap: Record<string, ComponentType<IconProps>> = {
  activity: Activity, users: Users, repeat: Repeat2, clock: Clock3, triangle: TriangleAlert,
  sparkles: Sparkles, 'layout-dashboard': LayoutDashboard, route: RouteIcon, 'users-round': UsersRound,
  lightbulb: Lightbulb, send: Send, 'upload-cloud': UploadCloud, 'book-open': BookOpen, info: Info,
};
const Icon = ({ name, ...props }: { name: string } & IconProps) => {
  const Component = iconMap[name] ?? Circle;
  return <Component {...props} />;
};

const cn = (...values: Array<string | false | null | undefined>) => values.filter(Boolean).join(' ');

function Logo({ compact = false, onLight = false }: { compact?: boolean; onLight?: boolean }) {
  if (!compact) {
    return (
      <div className={cn('flex items-center overflow-hidden', !onLight && 'rounded-xl bg-[#f4eddf] px-3 py-2')} data-testid="brand-pulso">
        <img src={pulsoLogo} alt="PULSO Petronect — Do clique à ação" className="h-11 w-auto max-w-[250px] object-contain object-left" />
      </div>
    );
  }
  return (
    <div className="flex items-center gap-3" data-testid="brand-pulso">
      <div className="relative grid h-9 w-9 place-items-center rounded-xl bg-[#f2e7d0]/10 ring-1 ring-[#f2e7d0]/20">
        <span className="absolute h-[2px] w-6 rotate-[-12deg] rounded-full bg-[#62BD4D]" />
        <span className="absolute h-2 w-2 translate-x-2 rounded-full bg-[#62BD4D] ring-4 ring-[#21483B]" />
        <span className="absolute h-2 w-2 -translate-x-2 rounded-full bg-[#FF6654] ring-4 ring-[#21483B]" />
      </div>
      {!compact && <div className="leading-none"><div className="font-display text-[20px] font-bold tracking-[.08em] text-white">PULSO</div><div className="mt-1 text-[9px] font-semibold uppercase tracking-[.18em] text-white/55">Do clique à ação</div></div>}
    </div>
  );
}

function Button({ children, variant = 'primary', className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'outline' | 'ghost' | 'soft' | 'coral' }) {
  return <button className={cn(
    'inline-flex min-h-9 items-center justify-center gap-2 rounded-lg px-3.5 text-sm font-semibold transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#1E5799]/35 disabled:cursor-not-allowed disabled:opacity-50',
    variant === 'primary' && 'bg-[#123F73] text-white shadow-[0_4px_10px_rgba(18,63,115,.18)] hover:bg-[#1E5799]',
    variant === 'outline' && 'border border-[#D7E0EA] bg-white text-[#123F73] hover:border-[#1E5799] hover:bg-[#F3F7FB]',
    variant === 'ghost' && 'text-[#52657A] hover:bg-[#EAF0F6] hover:text-[#123F73]',
    variant === 'soft' && 'bg-[#EAF1F8] text-[#1E5799] hover:bg-[#DDE9F5]',
    variant === 'coral' && 'bg-[#FF6654] text-white shadow-[0_4px_10px_rgba(255,102,84,.18)] hover:bg-[#e95545]',
    className,
  )} {...props}>{children}</button>;
}

function Badge({ children, color = 'blue' }: { children: ReactNode; color?: 'blue' | 'green' | 'coral' | 'amber' | 'slate' }) {
  const colors = {
    blue: 'bg-[#E7EFF8] text-[#1E5799]', green: 'bg-[#E7F5E4] text-[#347629]',
    coral: 'bg-[#FFF0EE] text-[#C94C40]', amber: 'bg-[#FFF4DF] text-[#956A1B]', slate: 'bg-[#EEF2F5] text-[#5A6C7E]',
  };
  return <span className={cn('inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold', colors[color])}>{children}</span>;
}

function Card({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <section className={cn('rounded-2xl border border-[#E0E7EF] bg-white shadow-[0_8px_28px_rgba(27,55,85,.045)]', className)}>{children}</section>;
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
    <div><div className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-[#1E5799]">{eyebrow ?? 'PULSO — Do clique à ação'}</div>
      <h1 className="font-display text-3xl font-bold tracking-[-.04em] text-[#172033] md:text-[34px]">{title}</h1>
      {description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#617286]">{description}</p>}</div>
    {actions && <div className="flex flex-wrap gap-2">{actions}</div>}
  </div>;
}

function GuidedDemo({ onClose, onGoOpportunity }: { onClose: () => void; onGoOpportunity: () => void }) {
  const [step, setStep] = useState(0);
  const steps = [
    { title: 'Cenário geral', text: 'Comece pela visão executiva: veja o volume de acessos, a evolução do retorno e os sinais que merecem atenção.', action: 'Explorar o cenário' },
    { title: 'Abrir oportunidade', text: 'Acesse a Central de Oportunidades para transformar um padrão de navegação em uma hipótese de ação.', action: 'Abrir oportunidade' },
    { title: 'Exibir evidências', text: 'Confira os sinais que sustentam a recomendação. Toda oportunidade mantém seu contexto explicável.', action: 'Ver evidências' },
    { title: 'Gerar comunicação', text: 'Escolha o segmento e gere uma mensagem contextual. A aprovação final continua humana.', action: 'Gerar comunicação' },
  ];
  const current = steps[step];
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#12243a]/55 p-4 backdrop-blur-sm">
    <div className="w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-2xl">
      <div className="flex items-center justify-between bg-[#123F73] p-5 text-white"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#9BD68D]">Demonstração guiada</div><h2 className="mt-1 font-display text-xl font-bold">Siga o pulso da decisão</h2></div><button aria-label="Fechar demonstração" data-testid="button-close-demo" onClick={onClose} className="rounded-lg p-2 text-white/70 hover:bg-white/10 hover:text-white"><X size={18} /></button></div>
      <div className="p-6"><div className="mb-7 flex gap-1.5">{steps.map((_, index) => <div key={index} className={cn('h-1.5 flex-1 rounded-full', index <= step ? 'bg-[#62BD4D]' : 'bg-[#E3EAF1]')} />)}</div>
        <div className="mb-5 grid h-12 w-12 place-items-center rounded-xl bg-[#E8F1F8] text-[#1E5799]"><span className="font-display text-lg font-bold">0{step + 1}</span></div>
        <h3 className="font-display text-2xl font-bold tracking-[-.03em] text-[#172033]">{current.title}</h3><p className="mt-3 leading-7 text-[#617286]">{current.text}</p>
        <div className="mt-7 flex items-center justify-between"><button data-testid="button-skip-demo" className="text-sm font-semibold text-[#718296] hover:text-[#123F73]" onClick={onClose}>Encerrar</button><div className="flex gap-2"><Button variant="outline" disabled={step === 0} onClick={() => setStep(s => s - 1)} data-testid="button-demo-previous"><ChevronLeft size={16} />Anterior</Button><Button onClick={() => { if (step === steps.length - 1) { onClose(); onGoOpportunity(); } else setStep(s => s + 1); }} data-testid="button-demo-next">{current.action}<ChevronRight size={16} /></Button></div></div>
      </div>
    </div>
  </div>;
}

