function MetricCard({ item }: { item: typeof metricData[number] }) {
  const iconColor = item.accent === 'green' ? 'text-[#347629] bg-[#E7F5E4]' : item.accent === 'coral' ? 'text-[#C94C40] bg-[#FFF0EE]' : 'text-[#1E5799] bg-[#E7EFF8]';
  return <Card className="p-4 transition-transform duration-200 hover:-translate-y-0.5"><div className="flex items-start justify-between"><div className={cn('grid h-9 w-9 place-items-center rounded-lg', iconColor)}><Icon name={item.icon} size={18} /></div><span className={cn('flex items-center gap-0.5 text-[11px] font-bold', item.change >= 0 ? 'text-[#347629]' : 'text-[#C94C40]')}>{item.change >= 0 ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}{Math.abs(item.change).toFixed(1).replace('.', ',')}%</span></div><div className="mt-4 font-display text-[27px] font-bold tracking-[-.04em] text-[#172033] tabular-nums">{item.value}</div><div className="mt-1 text-xs font-semibold text-[#52657A]">{item.label}</div><div className="mt-1 text-[11px] text-[#8A99A8]">{item.detail} <span className="text-[#A9B5C1]">· vs. período anterior</span></div></Card>;
}

function downloadSummary() {
  const csv = ['indicador,valor,variação', ...metricData.map(item => `"${item.label}","${item.value}","${item.change}%"`)].join('\n');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = 'pulso-resumo.csv';
  link.click();
  URL.revokeObjectURL(url);
}

