function Journey() {
  const [selected, setSelected] = useState('USR-024');
  const stages = [{ label: 'Entrada', count: 500, color: '#1E5799' }, { label: 'Página inicial', count: 438, color: '#4381B9' }, { label: 'Oportunidade', count: 316, color: '#62BD4D' }, { label: 'Documentação', count: 204, color: '#8BCF7B' }, { label: 'Próxima ação', count: 127, color: '#D89A3C' }];
  return <><PageHeader title="Jornada dos usuários" description="Entenda como os usuários atravessam o ecossistema, do primeiro clique à próxima ação." actions={<Button variant="soft" data-testid="button-journey-filter"><ListFilter size={15} />Filtrar jornada</Button>} />
    <div className="grid gap-5 xl:grid-cols-[1fr_340px]"><div className="space-y-5"><Card className="p-5"><div className="mb-6 flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Fluxo de navegação</h2><p className="mt-1 text-xs text-[#8391A0]">Conversão por etapa no período analisado</p></div><Badge color="green">25,4% chegam à ação</Badge></div><div className="flex flex-col gap-3 md:flex-row md:items-center md:gap-1">{stages.map((stage, index) => <div key={stage.label} className="flex min-w-0 flex-1 items-center gap-2"><div className="min-w-0 flex-1 rounded-xl border border-[#E1E8EF] bg-[#FBFCFD] p-3" data-testid={`stage-journey-${index}`}><div className="flex items-center justify-between gap-2"><span className="truncate text-xs font-bold text-[#52657A]">{stage.label}</span><span className="font-display text-lg font-bold text-[#172033]">{stage.count}</span></div><div className="mt-2 h-1.5 rounded-full bg-[#E9EEF3]"><div className="h-full rounded-full" style={{ backgroundColor: stage.color, width: `${(stage.count / 500) * 100}%` }} /></div><div className="mt-1 text-[10px] text-[#8B9AA8]">{((stage.count / 500) * 100).toFixed(1).replace('.', ',')}% da entrada</div></div>{index < stages.length - 1 && <ChevronRight className="hidden shrink-0 text-[#B9C5D0] md:block" size={18} />}</div>)}</div></Card>
      <Card className="p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Sessões recentes</h2><p className="mt-1 text-xs text-[#8391A0]">Clique para exibir a linha do tempo</p></div><Search size={17} className="text-[#8C9BAB]" /></div><div className="divide-y divide-[#EDF1F5]">{['USR-024', 'USR-041', 'USR-008', 'USR-052', 'USR-017'].map((user, index) => <button key={user} onClick={() => setSelected(user)} data-testid={`button-session-${user}`} className={cn('flex w-full items-center gap-3 py-3 text-left transition-colors', selected === user && 'rounded-lg bg-[#F2F7FB] px-2')}><div className="grid h-8 w-8 place-items-center rounded-full bg-[#E6EEF7] text-[10px] font-bold text-[#1E5799]">{user.slice(-3)}</div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-[#34485D]">{user}</div><div className="mt-1 truncate text-[10px] text-[#8796A5]">{['Oportunidade · Documentação', 'Entrada · Página inicial', 'Busca · Documentação', 'Página inicial · Suporte', 'Oportunidade · Próxima ação'][index]}</div></div><div className="text-right"><div className="text-[10px] font-semibold text-[#52657A]">{['04:32', '01:48', '06:12', '03:09', '08:44'][index]}</div><div className="mt-1 text-[10px] text-[#95A2AF]">há {index + 1}h</div></div></button>)}</div></Card></div>
      <Card className="overflow-hidden"><div className="border-b border-[#E5EBF1] bg-[#F8FAFC] p-5"><div className="text-[10px] font-bold uppercase tracking-[.16em] text-[#1E5799]">Linha do tempo</div><h2 className="mt-1 font-display text-lg font-bold">{selected}</h2><p className="mt-1 text-xs text-[#8391A0]">Sessão anonimizada selecionada</p></div><div className="p-5"><div className="relative ml-2 border-l border-[#D9E3EC] pl-6">{[['09:18', 'Entrada', 'Acesso ao ecossistema'], ['09:19', 'Página inicial', 'Visualizou 4 atalhos'], ['09:22', 'Oportunidade', 'Abriu oportunidade 2026-04'], ['09:25', 'Documentação', 'Baixou termo de referência'], ['09:31', 'Próxima ação', 'Retornou para contato']].map((item, index) => <div key={item[0]} className="relative pb-6 last:pb-0"><span className={cn('absolute -left-[31px] top-0.5 h-2.5 w-2.5 rounded-full border-2 border-white', index === 4 ? 'bg-[#62BD4D]' : 'bg-[#1E5799]')} /><div className="text-[10px] font-bold text-[#1E5799]">{item[0]}</div><div className="mt-1 text-xs font-bold text-[#34485D]">{item[1]}</div><div className="mt-1 text-[11px] leading-5 text-[#8796A5]">{item[2]}</div></div>)}</div></div></Card></div>
  </>;
}

function Segments() {
  const [filter, setFilter] = useState('Todos');
  const list = filter === 'Todos' ? segmentData : segmentData.filter(item => item.priority === filter);
  return <><PageHeader title="Segmentos comportamentais" description="Agrupamentos acionáveis a partir de padrões de navegação, sem identificação pessoal." actions={<div className="flex rounded-lg border border-[#D7E0EA] bg-white p-1">{['Todos', 'Alta', 'Média', 'Baixa'].map(item => <button key={item} onClick={() => setFilter(item)} data-testid={`button-segment-filter-${item.toLowerCase()}`} className={cn('rounded-md px-3 py-1.5 text-xs font-bold', filter === item ? 'bg-[#123F73] text-white' : 'text-[#718296] hover:bg-[#F0F4F8]')}>{item}</button>)}</div>} />
    <div className="mb-5 grid grid-cols-2 gap-3 md:grid-cols-4"><Card className="p-4"><div className="text-xs font-semibold text-[#7D8D9E]">Usuários classificados</div><div className="mt-2 font-display text-2xl font-bold">500</div><div className="mt-1 text-[11px] text-[#347629]">+8,6% no período</div></Card><Card className="p-4"><div className="text-xs font-semibold text-[#7D8D9E]">Prioridade alta</div><div className="mt-2 font-display text-2xl font-bold text-[#C94C40]">03</div><div className="mt-1 text-[11px] text-[#7D8D9E]">segmentos monitorados</div></Card><Card className="p-4"><div className="text-xs font-semibold text-[#7D8D9E]">Maior segmento</div><div className="mt-2 font-display text-2xl font-bold text-[#1E5799]">32,8%</div><div className="mt-1 text-[11px] text-[#7D8D9E]">Interessado</div></Card><Card className="p-4"><div className="text-xs font-semibold text-[#7D8D9E]">Reengajados</div><div className="mt-2 font-display text-2xl font-bold text-[#347629]">31</div><div className="mt-1 text-[11px] text-[#347629]">+8,9% vs. anterior</div></Card></div>
    <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="border-b border-[#E5EBF1] bg-[#FAFBFC] text-[10px] uppercase tracking-[.14em] text-[#8493A2]"><tr><th className="px-5 py-4">Segmento</th><th className="px-4 py-4">Quantidade</th><th className="px-4 py-4">Participação</th><th className="px-4 py-4">Tendência</th><th className="px-4 py-4">Comportamento observado</th><th className="px-4 py-4">Prioridade</th><th className="px-5 py-4">Ações</th></tr></thead><tbody className="divide-y divide-[#EDF1F5]">{list.map(item => <tr key={item.key} data-testid={`row-segment-${item.key}`} className="transition-colors hover:bg-[#FBFCFD]"><td className="px-5 py-4"><div className="flex items-center gap-3"><span className="h-2.5 w-2.5 rounded-full" style={{ background: item.color }} /><span className="text-sm font-bold text-[#34485D]">{item.key}</span></div></td><td className="px-4 py-4 font-display text-base font-bold">{item.count}</td><td className="px-4 py-4"><div className="flex items-center gap-2"><div className="h-1.5 w-16 rounded-full bg-[#E8EEF3]"><div className="h-full rounded-full bg-[#1E5799]" style={{ width: `${item.percentage * 2.5}%` }} /></div><span className="text-xs text-[#64778B]">{item.percentage.toFixed(1).replace('.', ',')}%</span></div></td><td className={cn('px-4 py-4 text-xs font-bold', item.trend >= 0 ? 'text-[#347629]' : 'text-[#C94C40]')}>{item.trend >= 0 ? '+' : ''}{item.trend.toFixed(1).replace('.', ',')}%</td><td className="max-w-[240px] px-4 py-4 text-xs leading-5 text-[#708194]">{item.behavior}</td><td className="px-4 py-4"><Badge color={item.priority === 'Alta' ? 'coral' : item.priority === 'Média' ? 'amber' : 'green'}>{item.priority}</Badge></td><td className="px-5 py-4"><Link href="/comunicacao" data-testid={`link-communicate-${item.key}`} className="inline-flex items-center gap-1 text-xs font-bold text-[#1E5799] hover:text-[#123F73]">Comunicar <ChevronRight size={14} /></Link></td></tr>)}</tbody></table></div></Card>
  </>;
}

function Opportunities() {
  const [selectedId, setSelectedId] = useState(opportunities[0].id);
  const [statusFilter, setStatusFilter] = useState('Todas');
  const [created, setCreated] = useState(false);
  const selected = opportunities.find(item => item.id === selectedId) ?? opportunities[0];
  const filtered = statusFilter === 'Todas' ? opportunities : opportunities.filter(item => item.status === statusFilter);
  return <><PageHeader title="Central de oportunidades" description="Sinais explicáveis que conectam comportamento observado a uma decisão possível." actions={<><select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} data-testid="select-opportunity-status" className="h-9 rounded-lg border border-[#D7E0EA] bg-white px-3 text-xs font-bold text-[#52657A] outline-none"><option>Todas</option><option>Nova</option><option>Em análise</option></select><Button onClick={() => setCreated(true)} data-testid="button-create-opportunity"><Plus size={15} />Criar comunicação</Button></>} />
    {created && <div className="mb-5 flex items-center justify-between rounded-xl border border-[#BFE2B6] bg-[#F0F9ED] p-3 text-sm text-[#347629]" data-testid="status-opportunity-created"><div className="flex items-center gap-2"><Check size={17} />Comunicação criada como rascunho.</div><button onClick={() => setCreated(false)} aria-label="Fechar aviso"><X size={16} /></button></div>}
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_400px]"><div className="space-y-3">{filtered.map(item => <button key={item.id} onClick={() => setSelectedId(item.id)} data-testid={`card-opportunity-${item.id}`} className={cn('w-full rounded-2xl border bg-white p-5 text-left shadow-[0_8px_28px_rgba(27,55,85,.045)] transition-all hover:border-[#B9CFE3]', selectedId === item.id ? 'border-[#1E5799] ring-2 ring-[#1E5799]/10' : 'border-[#E0E7EF]')}><div className="flex items-start justify-between gap-3"><div className="flex items-start gap-3"><div className={cn('grid h-10 w-10 shrink-0 place-items-center rounded-xl', item.severity === 'Alta' ? 'bg-[#FFF0EE] text-[#C94C40]' : 'bg-[#FFF4DF] text-[#956A1B]')}><Lightbulb size={19} /></div><div><h2 className="font-display text-base font-bold text-[#172033]">{item.title}</h2><div className="mt-2 flex flex-wrap items-center gap-2"><Badge color={item.severity === 'Alta' ? 'coral' : 'amber'}>{item.severity} prioridade</Badge><span className="text-[11px] text-[#8695A4]">Segmento: <b className="text-[#52657A]">{item.segment}</b></span></div></div></div><ChevronRight size={18} className={cn('mt-1 text-[#AAB8C5]', selectedId === item.id && 'text-[#1E5799]')} /></div><p className="mt-4 text-sm leading-6 text-[#687B8E]">{item.summary}</p><div className="mt-4 flex items-center gap-5 border-t border-[#EEF2F5] pt-3 text-[11px] text-[#8695A4]"><span className="flex items-center gap-1.5"><Target size={14} className="text-[#1E5799]" />{item.confidence}% confiança</span><span className="flex items-center gap-1.5"><Activity size={14} className="text-[#62BD4D]" />Impacto em {item.impact.toLowerCase()}</span><Badge color="slate">{item.status}</Badge></div></button>)}</div>
      <Card className="h-fit overflow-hidden"><div className="border-b border-[#E5EBF1] bg-[#FAFBFC] p-5"><div className="flex items-center justify-between"><Badge color="blue">Evidências</Badge><button data-testid="button-more-opportunity" className="rounded-md p-1.5 text-[#7E8E9D] hover:bg-[#E9EFF5]"><MoreHorizontal size={17} /></button></div><h2 className="mt-4 font-display text-xl font-bold tracking-[-.03em] text-[#172033]">{selected.title}</h2><p className="mt-2 text-xs leading-5 text-[#718296]">{selected.summary}</p></div><div className="p-5"><div className="mb-2 text-[10px] font-bold uppercase tracking-[.16em] text-[#8493A2]">Sinais observados</div><div className="space-y-3">{selected.evidence.map((evidence, index) => <div key={evidence} className="flex gap-3 rounded-lg bg-[#F7F9FB] p-3"><span className="grid h-5 w-5 shrink-0 place-items-center rounded-full bg-[#E4F2E0] text-[10px] font-bold text-[#347629]">{index + 1}</span><span className="text-xs leading-5 text-[#52657A]">{evidence}</span></div>)}</div><div className="mt-6 rounded-xl border border-[#CBE0F1] bg-[#F2F7FB] p-4"><div className="flex items-center gap-2 text-xs font-bold text-[#1E5799]"><Sparkles size={15} />Recomendação</div><p className="mt-2 text-xs leading-5 text-[#52657A]">{selected.recommendation}</p></div><Link href="/comunicacao" data-testid="link-create-from-opportunity" className="mt-5 flex h-10 w-full items-center justify-center gap-2 rounded-lg bg-[#123F73] text-sm font-bold text-white hover:bg-[#1E5799]"><MessageSquareText size={16} />Criar comunicação para este segmento</Link><div className="mt-3 flex items-start gap-2 text-[10px] leading-4 text-[#8A99A8]"><Info size={13} className="mt-0.5 shrink-0 text-[#1E5799]" />Esta sugestão é uma hipótese de ação. Revise o contexto antes de ativar.</div></div></Card></div>
  </>;
}

function Communication() {
  const [segment, setSegment] = useState<SegmentKey>('Com dificuldade');
  const [channel, setChannel] = useState('E-mail');
  const [tone, setTone] = useState('Orientativo');
  const [copied, setCopied] = useState(false);
  const [version, setVersion] = useState(0);
  const [approved, setApproved] = useState(false);
  const copyText = () => { navigator.clipboard?.writeText(`Olá, ${segment}. Identificamos uma oportunidade para facilitar seu próximo acesso à documentação Petronect. Acesse o caminho recomendado e encontre a informação com mais clareza.`); setCopied(true); window.setTimeout(() => setCopied(false), 1600); };
  return <><PageHeader title="Comunicação inteligente" description="Converta uma oportunidade em um rascunho contextual. A revisão humana é sempre a etapa final." actions={<Badge color="amber"><LockKeyhole size={12} />Demonstração local</Badge>} />
    <div className="grid gap-5 xl:grid-cols-[360px_1fr]"><Card className="p-5"><div className="mb-5 flex items-center gap-2"><div className="grid h-8 w-8 place-items-center rounded-lg bg-[#E8F1F8] text-[#1E5799]"><Settings2 size={16} /></div><div><h2 className="font-display text-base font-bold">Configurar mensagem</h2><p className="text-[11px] text-[#8391A0]">Defina o contexto da comunicação</p></div></div><div className="space-y-4">{[['Segmento', segment, setSegment, segmentData.map(item => item.key)], ['Objetivo', 'Reduzir abandono', () => {}, ['Reduzir abandono', 'Aumentar retorno', 'Orientar acesso']], ['Canal', channel, setChannel, ['E-mail', 'Banner no portal', 'Notificação']], ['Tom', tone, setTone, ['Orientativo', 'Direto', 'Institucional']]].map(([label, value, setter, options]) => <label key={label as string} className="block"><span className="mb-1.5 block text-xs font-bold text-[#52657A]">{label as string}</span><select value={value as string} onChange={e => (setter as (value: string) => void)(e.target.value)} disabled={label === 'Objetivo'} data-testid={`select-communication-${String(label).toLowerCase()}`} className="h-10 w-full rounded-lg border border-[#D7E0EA] bg-white px-3 text-sm text-[#34485D] outline-none focus:border-[#1E5799]">{(options as string[]).map(option => <option key={option}>{option}</option>)}</select></label>)}</div><div className="mt-6 rounded-xl bg-[#F5F8FB] p-4"><div className="flex items-center gap-2 text-xs font-bold text-[#52657A]"><Lightbulb size={14} className="text-[#D89A3C]" />Oportunidade conectada</div><p className="mt-2 text-xs leading-5 text-[#718296]">Busca sem retorno na documentação</p><button className="mt-2 text-xs font-bold text-[#1E5799]" data-testid="button-change-opportunity">Trocar oportunidade</button></div></Card>
      <Card className="overflow-hidden"><div className="border-b border-[#E5EBF1] bg-[#FAFBFC] px-6 py-4"><div className="flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.16em] text-[#1E5799]">Rascunho {version > 0 ? `v${version + 1}` : 'v1'}</div><h2 className="mt-1 font-display text-lg font-bold">Mensagem para {segment}</h2></div><Badge color={approved ? 'green' : 'amber'}>{approved ? 'Aprovada na simulação' : 'Revisão pendente'}</Badge></div></div><div className="p-6"><div className="mb-2 flex items-center justify-between"><label htmlFor="communication-subject" className="text-xs font-bold text-[#52657A]">Assunto</label><span className="text-[10px] text-[#94A1AE]">Editável</span></div><input id="communication-subject" defaultValue="Encontre a documentação que você precisa" data-testid="input-communication-subject" className="mb-5 h-10 w-full rounded-lg border border-[#D7E0EA] px-3 text-sm font-semibold text-[#34485D] outline-none focus:border-[#1E5799]" /><label htmlFor="communication-body" className="mb-2 block text-xs font-bold text-[#52657A]">Corpo da mensagem</label><textarea id="communication-body" key={`${segment}-${version}`} defaultValue={`Olá, ${segment}. Identificamos uma oportunidade para facilitar seu próximo acesso à documentação Petronect.\\n\\nEncontre o caminho recomendado com mais clareza e avance com segurança na sua próxima etapa. Acesse a área de documentação para consultar os materiais relacionados à sua jornada.`} data-testid="textarea-communication-body" className="min-h-[220px] w-full resize-y rounded-lg border border-[#D7E0EA] p-3 text-sm leading-7 text-[#52657A] outline-none focus:border-[#1E5799]" /><div className="mt-5 flex flex-wrap gap-2"><Button variant="outline" onClick={copyText} data-testid="button-copy-communication"><Copy size={15} />{copied ? 'Copiado' : 'Copiar conteúdo'}</Button><Button variant="soft" onClick={() => setVersion(v => v + 1)} data-testid="button-generate-version"><RefreshCw size={15} />Gerar outra versão</Button><Button onClick={() => setApproved(true)} data-testid="button-approve-communication"><Check size={15} />Aprovar simulação</Button></div><div className="mt-5 flex items-start gap-2 rounded-lg border border-[#F1DFC1] bg-[#FFF9ED] p-3 text-[11px] leading-5 text-[#856523]"><AlertTriangle size={15} className="mt-0.5 shrink-0" />A comunicação é uma simulação. Faça revisão humana de conteúdo, público e contexto antes de qualquer publicação.</div></div></Card></div>
  </>;
}

function ImportData() {
  const [dragging, setDragging] = useState(false);
  const [file, setFile] = useState<string | null>(() => getStored<string | null>('pulso-import-file', null));
  const [mapped, setMapped] = useState(false);
  const [error, setError] = useState(false);
  const handleFile = (name?: string) => { if (!name) return; if (!name.toLowerCase().endsWith('.csv')) { setError(true); return; } setError(false); setFile(name); setStored('pulso-import-file', name); };
  return <><PageHeader title="Importar dados" description="Atualize a análise com um CSV anonimizado, mantendo o mesmo contrato de dados da demonstração." actions={<Button variant="outline" onClick={() => { const csv = 'user_id,timestamp,page,action,duration\\nUSR-001,2026-05-01T09:00:00Z,/inicio,visualização,84'; const blob = new Blob([csv], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'exemplo-pulso.csv'; link.click(); URL.revokeObjectURL(url); }} data-testid="button-download-example"><Download size={15} />Baixar CSV de exemplo</Button>} />
    {error && <div className="mb-5 flex items-center gap-2 rounded-xl border border-[#F0C5C0] bg-[#FFF3F1] p-3 text-sm text-[#B94A40]" data-testid="status-import-error"><TriangleAlert size={17} />Formato inválido. Envie um arquivo CSV.</div>}
    <div className="grid gap-5 xl:grid-cols-[1fr_390px]"><Card className="p-6"><div onDragOver={e => { e.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={e => { e.preventDefault(); setDragging(false); handleFile(e.dataTransfer.files[0]?.name); }} className={cn('flex min-h-[260px] flex-col items-center justify-center rounded-2xl border-2 border-dashed transition-colors', dragging ? 'border-[#1E5799] bg-[#F0F6FB]' : 'border-[#C9D6E2] bg-[#FCFDFE]')}><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#E8F1F8] text-[#1E5799]"><UploadCloud size={25} /></div><h2 className="mt-5 font-display text-lg font-bold">Arraste seu CSV aqui</h2><p className="mt-2 text-center text-sm text-[#8493A2]">ou selecione um arquivo de até 10 MB para começar</p><label className="mt-5 inline-flex h-10 cursor-pointer items-center gap-2 rounded-lg bg-[#123F73] px-4 text-sm font-bold text-white hover:bg-[#1E5799]"><UploadCloud size={15} />Selecionar arquivo<input type="file" accept=".csv,text/csv" className="hidden" onChange={e => handleFile(e.target.files?.[0]?.name)} data-testid="input-import-file" /></label></div>{file && <div className="mt-5 flex items-center gap-3 rounded-xl border border-[#DCE6EE] bg-[#F8FAFC] p-3" data-testid="status-import-file"><div className="grid h-9 w-9 place-items-center rounded-lg bg-[#E7F5E4] text-[#347629]"><FileText size={18} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{file}</div><div className="text-[11px] text-[#8796A5]">Arquivo pronto para prévia</div></div><button onClick={() => { setFile(null); setStored('pulso-import-file', null); }} aria-label="Remover arquivo" data-testid="button-remove-file" className="rounded-md p-1 text-[#95A2AF] hover:bg-[#E9EFF5]"><X size={16} /></button></div>}</Card>
      <Card className="p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Contrato de dados</h2><p className="mt-1 text-xs text-[#8391A0]">Colunas esperadas pelo PULSO</p></div><Badge color="green">5 colunas</Badge></div><div className="space-y-3">{['user_id', 'timestamp', 'page', 'action', 'duration'].map((column, index) => <div key={column} className="flex items-center justify-between rounded-lg border border-[#E6ECF2] px-3 py-2.5"><div className="flex items-center gap-2"><span className="font-mono text-xs font-bold text-[#1E5799]">{column}</span>{index < 2 && <span className="text-[9px] font-bold uppercase text-[#C94C40]">obrigatória</span>}</div><span className="text-[10px] text-[#8796A5]">{['texto', 'data ISO', 'texto', 'texto', 'segundos'][index]}</span></div>)}</div><div className="mt-5 border-t border-[#E9EEF3] pt-4"><Button className="w-full" disabled={!file} onClick={() => setMapped(true)} data-testid="button-validate-import"><Check size={15} />{mapped ? 'Dados validados' : 'Validar e atualizar análise'}</Button></div></Card></div>
    {mapped && <Card className="mt-5 overflow-hidden"><div className="flex items-center gap-3 border-b border-[#DCEAD8] bg-[#F2FAEF] px-5 py-4 text-[#347629]"><Check size={18} /><div><div className="text-sm font-bold">Prévia validada com sucesso</div><div className="mt-1 text-xs">360 registros mapeados. A análise demonstrativa foi atualizada localmente.</div></div></div><div className="overflow-x-auto p-5"><table className="w-full min-w-[640px] text-left text-xs"><thead className="border-b border-[#E5EBF1] text-[10px] uppercase tracking-[.12em] text-[#8493A2]"><tr>{['user_id', 'timestamp', 'page', 'action', 'duration'].map(column => <th key={column} className="px-3 py-2">{column}</th>)}</tr></thead><tbody><tr>{['USR-001', '2026-05-01 09:00', '/inicio', 'visualização', '84'].map((value, index) => <td key={index} className="px-3 py-3 font-mono text-[#52657A]">{value}</td>)}</tr></tbody></table></div></Card>}
  </>;
}

function Methodology() {
  const steps = ['Anonimizar', 'Organizar', 'Identificar padrões', 'Formar segmentos', 'Priorizar sinais', 'Recomendar ações', 'Revisar com pessoas'];
  return <><PageHeader title="Metodologia transparente" description="O PULSO foi desenhado para explicar como cada sinal nasce — e onde a decisão humana entra." /><div className="grid gap-5 xl:grid-cols-[1.1fr_1fr]"><Card className="p-6"><div className="mb-6 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#E8F1F8] text-[#1E5799]"><RouteIcon size={20} /></div><div><h2 className="font-display text-lg font-bold">Processo em 7 etapas</h2><p className="text-xs text-[#8391A0]">Do evento bruto à ação contextual</p></div></div><div className="space-y-3">{steps.map((step, index) => <div key={step} className="flex items-center gap-3 rounded-xl border border-[#E7EDF2] p-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-[#123F73] font-display text-sm font-bold text-white">{index + 1}</div><div className="flex-1"><div className="text-sm font-bold text-[#34485D]">{step}</div><div className="mt-0.5 text-[11px] text-[#8796A5]">{['Remove identificadores diretos e preserva apenas o necessário.', 'Padroniza eventos, horários e caminhos de navegação.', 'Encontra repetições, quedas e mudanças de comportamento.', 'Agrupa perfis por sinais e contexto, não por identidade.', 'Combina impacto, confiança e possibilidade de ação.', 'Sugere uma hipótese que conecta sinal a resposta.', 'Valida contexto, linguagem e impacto antes de ativar.'][index]}</div></div><ChevronRight size={16} className="text-[#B6C3CF]" /></div>)}</div></Card><div className="space-y-5"><Card className="p-6"><div className="mb-5 flex items-center gap-2"><LockKeyhole size={18} className="text-[#1E5799]" /><h2 className="font-display text-lg font-bold">Princípios de confiança</h2></div><div className="grid gap-4 sm:grid-cols-2">{[['Transparência', 'Mostramos o porquê de cada indicação.'], ['Explicabilidade', 'Evidências acompanham a recomendação.'], ['Minimização', 'Usamos apenas o necessário para a análise.'], ['Privacidade', 'Usuários aparecem como USR-001.'], ['LGPD', 'A demonstração considera finalidade e contexto.'], ['Não discriminação', 'Nenhuma segmentação usa atributos sensíveis.']].map(([title, text]) => <div key={title} className="rounded-xl bg-[#F7F9FB] p-3"><div className="flex items-center gap-2 text-xs font-bold text-[#34485D]"><Check size={14} className="text-[#62BD4D]" />{title}</div><p className="mt-2 text-[11px] leading-5 text-[#8796A5]">{text}</p></div>)}</div></Card><Card className="border-l-4 border-l-[#FF6654] p-6"><div className="flex items-start gap-3"><AlertTriangle className="mt-0.5 shrink-0 text-[#FF6654]" size={18} /><div><h2 className="font-display text-base font-bold">Supervisão humana é obrigatória</h2><p className="mt-2 text-xs leading-6 text-[#687B8E]">O PULSO não decide por pessoas. Ele organiza evidências para que equipes analisem contexto, revisem linguagem e escolham a próxima ação.</p></div></div></Card></div></div></>;
}

function About() {
  return <><PageHeader eyebrow="HACKATHON CONEXÃO ANCESTRAL 2026" title="Sobre o projeto" description="Uma demonstração de como transformar rastros de navegação em decisões de negócio mais humanas e explicáveis." /><div className="grid gap-5 xl:grid-cols-[1.2fr_1fr]"><Card className="overflow-hidden"><div className="bg-[#123F73] p-7 text-white md:p-9"><div className="mb-8 flex items-center gap-3"><Logo /><div className="hidden h-6 w-px bg-white/20 sm:block" /><span className="hidden text-xs font-semibold text-white/60 sm:block">Hackathon Conexão Ancestral 2026</span></div><h2 className="max-w-xl font-display text-3xl font-bold leading-tight tracking-[-.04em] md:text-4xl">Do clique à ação,<br /><span className="text-[#9BD68D]">com contexto.</span></h2><p className="mt-5 max-w-lg text-sm leading-7 text-white/65">O PULSO transforma registros de navegação anonimizados em indicadores, segmentos, alertas explicáveis, oportunidades e recomendações para o ecossistema Petronect.</p></div><div className="grid gap-4 p-6 sm:grid-cols-3"><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8A99A8]">Realização</div><div className="mt-2 text-sm font-bold text-[#34485D]">Petronect</div></div><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8A99A8]">Execução</div><div className="mt-2 text-sm font-bold text-[#34485D]">KODIE Academy</div></div><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8A99A8]">Natureza</div><div className="mt-2 text-sm font-bold text-[#34485D]">Demonstrativa</div></div></div></Card><div className="space-y-5"><Card className="p-6"><div className="mb-5 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.16em] text-[#1E5799]">Equipe 10</div><h2 className="mt-1 font-display text-xl font-bold">Pessoas por trás do pulso</h2></div><UsersRound size={21} className="text-[#1E5799]" /></div><div className="space-y-2">{['Ana Beatriz · Produto', 'Bruno Lima · Dados', 'Camila Nunes · Experiência', 'Diego Reis · Tecnologia', 'Elisa Martins · Estratégia'].map((person, index) => <div key={person} className="flex items-center gap-3 rounded-lg bg-[#F7F9FB] px-3 py-2.5"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#DDEAF5] text-[10px] font-bold text-[#1E5799]">{['AB', 'BL', 'CN', 'DR', 'EM'][index]}</div><span className="text-xs font-semibold text-[#52657A]">{person}</span></div>)}</div></Card><Card className="p-6"><div className="flex items-start gap-3"><Info size={18} className="mt-0.5 text-[#1E5799]" /><div><h2 className="font-display text-base font-bold">Sobre os dados</h2><p className="mt-2 text-xs leading-6 text-[#718296]">Esta interface usa dados simulados locais para uma apresentação segura. Não há API, banco, chave externa ou identificação pessoal envolvida.</p></div></div></Card></div></div></>;
}

function Login() {
  const [, setLocation] = useLocation();
  const [email, setEmail] = useState('analista@petronect.com.br');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (password !== '123456') {
      setError('Senha demonstrativa incorreta. Use 123456 para continuar.');
      return;
    }
    setError('');
    setLoading(true);
    setStored('pulso-auth', true);
    window.setTimeout(() => setLocation('/'), 500);
  };
  return <div className="login-editorial flex min-h-[100dvh] bg-[#123F73]"><div className="relative hidden flex-1 overflow-hidden lg:flex lg:flex-col lg:justify-between p-12"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px)', backgroundSize: '36px 36px' }} /><div className="relative"><Logo /><div className="mt-24 max-w-xl"><div className="mb-5 flex items-center gap-2 text-xs font-bold uppercase tracking-[.2em] text-[#9BD68D]"><span className="h-px w-8 bg-[#9BD68D]" />Inteligência comportamental</div><h1 className="font-display text-6xl font-bold leading-[1.03] tracking-[-.06em] text-white">Transforme acessos<br />em <span className="text-[#9BD68D]">decisões</span><br />acionáveis.</h1><p className="mt-7 max-w-md text-base leading-7 text-white/60">Uma leitura mais clara das jornadas que acontecem dentro do ecossistema Petronect.</p></div></div><div className="relative flex items-end justify-between text-xs text-white/45"><span>Hackathon Conexão Ancestral 2026</span><span>Equipe 10</span></div></div><div className="flex w-full max-w-[520px] flex-col justify-center bg-[#F5F7FA] p-6 sm:p-12"><div className="mb-12 lg:hidden"><Logo onLight /></div><div className="mx-auto w-full max-w-[360px]"><div className="mb-9"><div className="mb-3 inline-flex rounded-full bg-[#E7EFF8] px-3 py-1 text-[10px] font-bold uppercase tracking-[.16em] text-[#1E5799]">Acesso demonstrativo</div><h2 className="font-display text-3xl font-bold tracking-[-.04em] text-[#172033]">Bem-vindo ao PULSO</h2><p className="mt-2 text-sm leading-6 text-[#718296]">Entre para explorar a análise comportamental.</p></div><form onSubmit={submit} className="space-y-5"><label className="block"><span className="mb-2 block text-xs font-bold text-[#52657A]">E-mail corporativo</span><div className="relative"><Mail size={16} className="absolute left-3 top-3 text-[#8A99A8]" /><input type="email" autoComplete="username" value={email} onChange={e => setEmail(e.target.value)} required data-testid="input-login-email" className="h-11 w-full rounded-lg border border-[#D7E0EA] bg-white pl-10 pr-3 text-sm text-[#34485D] outline-none focus:border-[#1E5799]" /></div></label><label className="block"><span className="mb-2 block text-xs font-bold text-[#52657A]">Senha</span><div className="relative"><LockKeyhole size={16} className="absolute left-3 top-3 text-[#8A99A8]" /><input type="password" autoComplete="current-password" value={password} onChange={e => { setPassword(e.target.value); setError(''); }} placeholder="Use 123456 para continuar" required aria-invalid={Boolean(error)} data-testid="input-login-password" className="h-11 w-full rounded-lg border border-[#D7E0EA] bg-white pl-10 pr-3 text-sm text-[#34485D] outline-none focus:border-[#1E5799]" /></div></label>{error && <p role="alert" className="-mt-2 text-xs font-semibold text-[#C94C40]">{error}</p>}<Button type="submit" className="mt-2 h-11 w-full" data-testid="button-login-submit"><LogIn size={16} />{loading ? 'Entrando na demonstração…' : 'Entrar na demonstração'}</Button></form><p className="mt-7 text-center text-[11px] leading-5 text-[#8A99A8]">Acesso local para apresentação · nenhum dado é enviado para fora desta demonstração.</p></div></div></div>;
}

function NotFound() {
  return <div className="grid min-h-[100dvh] place-items-center bg-[#F5F7FA] p-6"><div className="text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#E8F1F8] text-[#1E5799]"><Search size={24} /></div><h1 className="mt-5 font-display text-3xl font-bold">Página não encontrada</h1><p className="mt-2 text-sm text-[#718296]">O caminho que você acessou não faz parte desta demonstração.</p><Link href="/" className="mt-6 inline-flex h-10 items-center rounded-lg bg-[#123F73] px-4 text-sm font-bold text-white" data-testid="link-back-home">Voltar para a visão geral</Link></div></div>;
}

function Router() {
  const [location] = useLocation();
  const auth = getStored('pulso-auth', false);
  if (location === '/login') return <Login />;
  if (!auth) return <Login />;
  return <Shell><Switch><Route path="/" component={Overview} /><Route path="/jornada" component={Journey} /><Route path="/segmentos" component={Segments} /><Route path="/oportunidades" component={Opportunities} /><Route path="/comunicacao" component={Communication} /><Route path="/importar" component={ImportData} /><Route path="/metodologia" component={Methodology} /><Route path="/sobre" component={About} /><Route component={NotFound} /></Switch></Shell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;